  'This thread stays read-only. Retry the move, or cancel it. Cancel unlocks the thread only after {value0} confirms that it removed its copy. If {value1} already received the thread, cancel finishes the move instead.':
    'Bu konu salt okunur olarak kalır. Taşıma işlemini yeniden deneyin veya iptal edin. İptal, yalnızca {value0}, kopyasını kaldırdığını onayladıktan sonra ileti dizisinin kilidini açar. {value1} iş parçacığını zaten almışsa, bunun yerine iptal işlemi işlemi bitirir.',
