  'Cancel move': 'Taşımayı iptal et',
  'Cancel copy': 'Kopyalamayı iptal et',
  'Move the full saved conversation, checklist, attachments and files. Provider sessions and credentials stay here. The destination thread uses that computer’s default harness, with no more access than this thread has. Nothing runs until you send the next message there. You can change its model after it opens. This thread stays here, read-only, for recovery.':
    'Kaydedilen görüşmenin tamamını, kontrol listesini, ekleri ve dosyaları taşıyın. Sağlayıcı oturumları ve kimlik bilgileri burada kalır. Hedef iş parçacığı, bu iş parçacığının sahip olduğundan daha fazla erişime sahip olmaksızın, o bilgisayarın varsayılan donanımını kullanır. Bir sonraki mesajı oraya gönderene kadar hiçbir şey çalışmaz. Açıldıktan sonra modelini değiştirebilirsiniz. Bu konu kurtarma için salt okunur olarak burada kalır.',
