  'Set up CuaDriver on this runtime host. CuaDriver owns OS permissions; Dovo connects agents through MCP.':
    "Bu çalışma zamanı ana bilgisayarında CuaDriver'ı kurun. CuaDriver işletim sistemi izinlerine sahiptir; Dovo, aracıları MCP aracılığıyla birbirine bağlar.",
  'Host executable names or paths, without shell quoting. Agent overrides take precedence. New terminals use these shell settings.':
    'Yürütülebilir adları veya yolları kabuktan alıntı yapmadan barındırın. Aracı geçersiz kılmaları önceliklidir. Yeni terminaller bu kabuk ayarlarını kullanır.',
