  'Enable agent computer use on this computer':
    'Bu bilgisayarda aracı bilgisayar kullanımını etkinleştir',
  'Grants writable agents access to this computer’s desktop. Read-only agents are excluded. The user and agents share the desktop and app state.':
    'Yazılabilir aracıların bu bilgisayarın masaüstüne erişmesine izin verir. Salt okunur aracılar hariçtir. Kullanıcı ve aracılar masaüstünü ve uygulama durumunu paylaşır.',
  'Leave Cua Driver empty to detect it on this computer’s PATH or in its standard installation folder. Changes apply to new agent turns.':
    "Bu bilgisayarın PATH'inde veya standart kurulum klasöründe algılamak için Cua Sürücüsünü boş bırakın. Değişiklikler yeni temsilci dönüşleri için geçerlidir.",
  '1. Install on this computer': '1. Bu bilgisayara yükleyin',
  'Run the official installer on the runtime host, then refresh status. It downloads and installs CuaDriver; no Cua account is required.':
    "Resmi yükleyiciyi çalışma zamanı ana bilgisayarında çalıştırın, ardından durumu yenileyin. CuaDriver'ı indirir ve yükler; Cua hesabı gerekmez.",
  'Minimal Linux systems need libxi6 and at-spi2-core. GNOME needs Cua’s bundled WinRects helper; see the installation guide.':
    "Minimal Linux sistemleri libxi6 ve at-spi2-core'a ihtiyaç duyar. GNOME'un Cua'nın paketlenmiş WinRects yardımcısına ihtiyacı var; kurulum kılavuzuna bakın.",
  'Install and set up Cua Driver': 'Cua Sürücüsünü yükleyin ve kurun',
  'Detect / check Cua Driver': 'Cua Sürücüsünü Algıla / Kontrol Et',
  '2. Permissions & desktop access': '2. İzinler ve masaüstü erişimi',
  '3. Agent MCP, skills & hooks': '3. Ajan MCP, beceriler ve kancalar',
  '4. Computer History (optional preview)': '4. Bilgisayar Geçmişi (isteğe bağlı önizleme)',
  'Grant macOS Accessibility and Screen Recording to CuaDriver and accept its relaunch. Test desktop access lists apps without changing them. Daemon controls affect active computer-use sessions.':
    "CuaDriver'a macOS Erişilebilirlik ve Ekran Kaydı verin ve yeniden başlatılmasını kabul edin. Masaüstü erişim listeleri uygulamalarını değiştirmeden test edin. Daemon kontrolleri aktif bilgisayar kullanım oturumlarını etkiler.",
  'Save the computer-use switch for automatic dovo_cua MCP on new writable turns. No manual MCP registration is needed. Install the optional official skill pack; installation links detected agents on this computer.':
    'Yeni yazılabilir dönüşlerde otomatik dovo_cua MCP için bilgisayar kullanım anahtarını kaydedin. Manuel MCP kaydına gerek yoktur. İsteğe bağlı resmi beceri paketini yükleyin; yükleme bağlantıları bu bilgisayardaki aracıları algıladı.',
  'Opt-in, encrypted, metadata-only history. Enable may restart the daemon. Disable keeps recorded data; pause temporarily stops recording. Unsupported builds report an error. Data stays on the runtime host; View recent history retrieves up to 20 events here.':
    "Kaydolunabilir, şifrelenmiş, yalnızca meta veri geçmişi. Etkinleştirme arka plan programını yeniden başlatabilir. Kayıtlı verileri saklamayı devre dışı bırakın; duraklatma kaydı geçici olarak durdurur. Desteklenmeyen derlemeler bir hata bildirir. Veriler çalışma zamanı ana bilgisayarında kalır; Yakın geçmişin görüntülenmesi burada 20'ye kadar olayı getirir.",
  'Delete recorded Computer History?': 'Kayıtlı Bilgisayar Geçmişi silinsin mi?',
  'Delete all recorded history and its encryption key on this computer. This cannot be undone.':
    'Bu bilgisayardaki tüm kayıtlı geçmişi ve şifreleme anahtarını silin. Bu geri alınamaz.',
