  'The agent, its commands and its terminals run in a container. Only this checkout and the harness login are mounted.':
    'Ajan, komutları ve terminalleri bir konteynerde çalışır. Yalnızca bu çalışma kopyası ve ajanın oturum bilgileri bağlanır.',
  'Holds new work that runs without your message once its estimated cost reaches the limit. This covers Bot follow-ups, Bot routine steps, scheduled messages and child agents. Each thread or Bot counts with its child agents. A routine without a Bot starts a new count on each run. Set its own limits in Monitoring and limits. Your next message or Continue resets the count. Turns without a price also hold work. A running turn always finishes.':
    'Mesajınız olmadan çalışan yeni işi, tahmini maliyeti sınıra ulaştığında bekletir. Bot devam adımları, bir Botun rutin adımları, zamanlanmış mesajlar ve alt ajanlar buna dahildir. Her ileti dizisi veya Bot, alt ajanlarıyla birlikte sayılır. Botu olmayan bir rutin her çalıştırmada yeni bir sayım başlatır. Onun kendi sınırlarını İzleme ve sınırlar bölümünde ayarlayın. Sonraki mesajınız veya Devam et sayımı sıfırlar. Fiyatı olmayan turlar da işi bekletir. Çalışan bir tur her zaman tamamlanır.',
